-- V004: row-level security and cache-version triggers. GENERATED by server/db/tools/gen-sql.ts.
--
-- RLS: seereon_app sees and writes only rows of current_setting('app.tenant_id') (set with SET LOCAL per
-- transaction). No tenant set => no rows. A platform super-admin request may additionally SET LOCAL
-- app.platform_admin = 'on' to work across tenants. Tables are owned by seereon_owner and RLS is not FORCEd,
-- so the owner (migrations, seed, auth/platform work) is not filtered.
--
-- Versions: statement-level AFTER INSERT/UPDATE/DELETE triggers with transition tables bump
-- tenant_table_versions(tenant_id, table_name) by exactly 1 per statement for every tenant the statement
-- touched (tenants: keyed by tenants.id). Out-of-band SQL writes therefore also invalidate API caches.

CREATE FUNCTION app_bump_table_versions() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $fn$
DECLARE
  tcol text := TG_ARGV[0];
BEGIN
  IF TG_OP = 'INSERT' THEN
    EXECUTE format('INSERT INTO tenant_table_versions AS v (tenant_id, table_name, version)
      SELECT DISTINCT %I, %L, 1 FROM new_rows WHERE %I IS NOT NULL
      ON CONFLICT (tenant_id, table_name) DO UPDATE SET version = v.version + 1', tcol, TG_TABLE_NAME, tcol);
  ELSIF TG_OP = 'UPDATE' THEN
    EXECUTE format('INSERT INTO tenant_table_versions AS v (tenant_id, table_name, version)
      SELECT %I, %L, 1 FROM (SELECT %I FROM new_rows UNION SELECT %I FROM old_rows) s WHERE %I IS NOT NULL
      ON CONFLICT (tenant_id, table_name) DO UPDATE SET version = v.version + 1', tcol, TG_TABLE_NAME, tcol, tcol, tcol);
  ELSE
    EXECUTE format('INSERT INTO tenant_table_versions AS v (tenant_id, table_name, version)
      SELECT DISTINCT %I, %L, 1 FROM old_rows WHERE %I IS NOT NULL
      ON CONFLICT (tenant_id, table_name) DO UPDATE SET version = v.version + 1', tcol, TG_TABLE_NAME, tcol);
  END IF;
  RETURN NULL;
END
$fn$;

ALTER TABLE tenants ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON tenants USING (id = current_setting('app.tenant_id', true)) WITH CHECK (id = current_setting('app.tenant_id', true));
CREATE POLICY platform_admin ON tenants USING (current_setting('app.platform_admin', true) = 'on') WITH CHECK (current_setting('app.platform_admin', true) = 'on');
CREATE TRIGGER tenants_ver_ins AFTER INSERT ON tenants REFERENCING NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION app_bump_table_versions('id');
CREATE TRIGGER tenants_ver_upd AFTER UPDATE ON tenants REFERENCING OLD TABLE AS old_rows NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION app_bump_table_versions('id');
CREATE TRIGGER tenants_ver_del AFTER DELETE ON tenants REFERENCING OLD TABLE AS old_rows FOR EACH STATEMENT EXECUTE FUNCTION app_bump_table_versions('id');

