GRANT SELECT, INSERT, UPDATE, DELETE ON tenants, users, invites, subscriptions, billing_invoices, holidays, delegations, projects, project_status_history, milestones, tasks, task_dependencies, comments, notifications, timesheet_weeks, timesheet_entries, leave, daily_updates, cost_rates, allocations, files, invoices, payments, payroll_runs, payroll_lines, ledger_entries, deals, deal_activities, deal_stage_history, change_requests, openings, ops_items, activity_log, saved_reports, task_reviews, documents, document_versions, document_acks, document_views, leave_requests, leave_policies, appraisal_cycles, appraisals, goals, feedback, candidates, interviews, lifecycle_checklists, assets, expense_claims, vendors, purchase_orders, vendor_bills, budgets, clients, contracts, revenue_leakage, objectives, key_results, data_exports, number_sequences, admin_audit, roles, change_sets, approval_workflows, locations, departments, designations, grades, cost_centres, shifts, email_templates, email_outbox, cost_estimates, wf_templates, wf_instances, doc_templates, issued_documents, employee_documents TO seereon_app;
